(() => {
'use strict';
const C=VetClinical,S=VetSurgery,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>Number(v).toLocaleString('ko-KR',{maximumFractionDigits:1});
const demo=new URLSearchParams(location.search).get('demo')==='1',key='vetdiet.surgery.v2',fields=['name','species','weight','ageWeeks','procedureType','profile','induction','recoveredAt','dailyKcal','usualMeals','finalInstructions'];let records=[],last,selectedFood='';
const dietProducts=()=>window.VetDietContext.products();
const sources=keys=>keys.map(k=>S.sources[k]?`<a href="${esc(S.sources[k][1])}" target="_blank" rel="noopener noreferrer">${esc(S.sources[k][0])}</a>`:'').join(' · ');
function notify(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,5000);}
function read(){const p={};fields.forEach(k=>p[k]=$('s-'+k).value);p.emergency=$('s-emergency').checked;return p;}
function validateRecord(r,legacy=false){
 if(!r||typeof r.id!=='string'||r.id.length>100||typeof r.savedAt!=='string'||!Number.isFinite(Date.parse(r.savedAt))||!r.patient||typeof r.patient.name!=='string'||r.patient.name.length>80)throw Error('수술 기록 형식 오류');
 if(legacy||r.legacy){const result=C.surgicalPlan(r.patient);if(!result.ok)throw Error('이전 기록의 입력값 오류');return{...r,result,legacy:true};}
 if(fields.some(k=>typeof r.patient[k]!=='string'||r.patient[k].length>3000)||typeof r.patient.emergency!=='boolean')throw Error('추천 기록의 입력값 오류');
 const f=r.foodSnapshot;if(f){if(!['rc','hills'].includes(f.brand)||!['dog','cat','both'].includes(f.species)||typeof f.id!=='string'||typeof f.name!=='string'||f.name.length>200||typeof f.url!=='string'||!/^https:\/\//i.test(f.url)||!Array.isArray(f.purposes)||f.purposes.some(x=>typeof x!=='string')||!Array.isArray(f.contra)||f.contra.some(x=>!x||typeof x.code!=='string')||!['kg','100g','g','pack'].includes(f.energyUnit)||(f.energy!==null&&(!Number.isFinite(Number(f.energy))||Number(f.energy)<=0))||Number(VetEngine.kcalPerGram(f))>10)throw Error('저장 사료 자료 오류');}
 const result=S.recommend(r.patient,f||null);if(!result.ok)throw Error(result.errors.join(' '));return{...r,result,legacy:false};
}
function validateBackup(d){if(!d||d.type!=='vetdiet-surgery'||![1,2].includes(d.version)||!Array.isArray(d.records)||d.records.length>5000)throw Error('수술 백업 형식 오류');return d.records.map(r=>validateRecord(r,d.version===1));}
try{if(!demo){const map=new Map();for(const k of ['vetdiet.surgery.v1',key]){const raw=localStorage.getItem(k);if(raw)validateBackup(JSON.parse(raw)).forEach(r=>map.set(r.id,r));}records=[...map.values()];}}catch{notify('기록을 읽지 못했습니다. 원본 저장 자료는 유지했습니다.');}
function persist(next){if(!demo)localStorage.setItem(key,JSON.stringify({type:'vetdiet-surgery',version:2,records:next}));records=next;}
S.procedures.forEach(p=>$('s-procedureType').add(new Option(p.name,p.id)));Object.entries(S.profiles).forEach(([k,v])=>$('s-profile').add(new Option(v,k)));
function render(){const p=read(),choices=S.candidateFoods(p,dietProducts());if(!choices.some(f=>f.id===selectedFood))selectedFood=choices[0]?.id||'';const food=choices.find(f=>f.id===selectedFood);last=S.recommend(p,food);
 $('s-food-controls').hidden=!choices.length;$('s-food').innerHTML=choices.map(f=>`<option value="${esc(f.id)}">${f.brand==='rc'?'로얄캐닌':'힐스'} · ${esc(f.name)}${f.type==='wet'?' · 습식':''}</option>`).join('');$('s-food').value=selectedFood;
 if(!last.ok){$('s-result').innerHTML=last.errors.map(t=>`<p class="notice">${esc(t)}</p>`).join('');}else{const r=last;
 $('s-result').innerHTML=`<div class="recommendation-block"><span class="pill">수술 전</span><h3>${esc(r.preText)}</h3><p>${esc(r.preDetail)}</p>${r.foodStopWindow?`<p>음식 중단 추천 범위: <b>${esc(r.foodStopWindow.join(' ~ '))}</b></p>`:''}</div><div class="recommendation-block"><span class="pill">수술 후 · 언제</span><h3>${esc(r.postTitle)}</h3><p>${esc(r.postDetail)}</p>${r.postClockWindow?`<p>마취 회복 시각 기준 참고: <b>${esc(r.postClockWindow.join(' ~ '))}</b></p>`:''}<p class="notice">급여 시작 조건: ${esc(r.condition)}</p></div><div class="recommendation-block"><span class="pill">무엇을</span><p>${esc(r.diet)}</p><p>${esc(r.specific)}</p>${food?`<p><a href="${esc(food.url)}" target="_blank" rel="noopener noreferrer">${food.brand==='rc'?'로얄캐닌':'힐스'} · ${esc(food.name)}</a></p><p class="muted">${esc(food.notes||'제품 열량은 국내 실제 포장과 확인하세요.')}</p>`:''}</div><div class="recommendation-block"><span class="pill">얼마나</span><h3>${esc(r.amountText)}</h3>${r.firstKcal!==null?`<p class="recommended-amount">첫 급여 ${r.firstGrams!==null?fmt(r.firstGrams)+' g · ':''}${fmt(r.firstKcal)} kcal</p>`:''}${r.dayKcal!==null?`<p>초기 하루 합계: ${r.dayGrams!==null?fmt(r.dayGrams)+' g · ':''}${fmt(r.dayKcal)} kcal → 하루 4회 분할 예시</p>`:''}<p class="muted">${esc(r.basis)}</p>${r.firstGrams!==null?'<p class="muted">g은 선택한 제품의 등록 열량을 사용한 환산 예시입니다. 실제 국내 포장 열량을 대조하세요. 불리는 경우 g은 물을 넣기 전 사료 무게입니다.</p>':''}</div>${r.warnings.map(t=>`<p class="warning">${esc(t)}</p>`).join('')}<details class="s-options"><summary>추천 근거 확인</summary><p class="clinical-sources">${sources(r.refs)}</p><p>자료 확인: ${S.checkedAt} · 최종 계획은 담당 수의사가 조정합니다.</p></details>`;}
 ['s-save','s-copy','s-print'].forEach(id=>$(id).disabled=!last.ok);
}
$('s-form').addEventListener('input',render);$('s-food').addEventListener('change',()=>{selectedFood=$('s-food').value;render();});document.querySelector('nav button[data-tab="surgery"]').addEventListener('click',render);
function report(p,r,savedAt,legacy=false){if(legacy)return['이전 버전 · 담당 수의사 작성 금식 계획',`환자: ${p.name} · ${p.weight} kg`,`시술: ${p.procedure}`,`마취 유도: ${r.induction}`,`음식 중단: ${r.foodStop} (${p.hours}시간)`,`물: ${p.waterMode==='free'?'자유 접근':r.waterStop}`,`수술 후: ${r.postText}`,`당시 지시: ${p.postInstructions||''}`,`저장: ${savedAt}`].join('\n');return['수술 전후 추천 안내',`환자: ${p.name||'미입력'} · ${p.species==='dog'?'강아지':'고양이'} · ${p.weight} kg · ${p.ageWeeks}주`,`수술: ${r.procedure.name} · 상태: ${S.profiles[p.profile]}`,'',r.preText,r.preDetail,r.foodStopWindow?'음식 중단 추천: '+r.foodStopWindow.join(' ~ '):'',r.postTitle,r.postDetail,r.postClockWindow?'회복 시각 기준 참고: '+r.postClockWindow.join(' ~ '):'','급여 시작 조건: '+r.condition,r.diet,r.specific,r.food?`제품 예시: ${r.food.brand==='rc'?'로얄캐닌':'힐스'} ${r.food.name}`:'',r.amountText,r.firstKcal!==null?`첫 급여: ${r.firstGrams!==null?fmt(r.firstGrams)+' g · ':''}${fmt(r.firstKcal)} kcal`:'',r.dayKcal!==null?`초기 하루 합계: ${r.dayGrams!==null?fmt(r.dayGrams)+' g · ':''}${fmt(r.dayKcal)} kcal · 4회 분할 예시`:'',r.basis,r.firstGrams!==null?'g은 등록 열량의 환산 예시입니다. 실제 국내 포장과 대조하세요. 불릴 때는 물을 넣기 전 사료 무게입니다.':'',...r.warnings,`담당 수의사 최종 지시: ${p.finalInstructions||'미입력'}`,savedAt?'저장: '+savedAt:'','근거:',...r.refs.map(k=>S.sources[k].join(' · ')),r.food?'제품 출처: '+r.food.url:''].filter(Boolean).join('\n');}
function showReport(t){$('clinical-report-text').value=t;$('clinical-report').showModal();}
$('s-copy').addEventListener('click',()=>{if(last.ok)showReport(report(read(),last));});$('clinical-close').addEventListener('click',()=>$('clinical-report').close());$('clinical-copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('clinical-report-text').value);notify('추천 안내문을 복사했습니다.');}catch{$('clinical-report-text').select();notify('안내문 텍스트를 선택해 복사하세요.');}});
$('s-print').addEventListener('click',()=>{if(last.ok){$('print-area').innerHTML=`<h1>수술 전후 추천 안내</h1><p>${esc(report(read(),last))}</p>`;window.print();}});
function renderRecords(){$('s-records').innerHTML=records.length?[...records].reverse().map(r=>`<article class="record"><div><h3>${esc(r.patient.name||'미입력')}</h3><p>${esc(r.legacy?r.patient.procedure:r.result.procedure.name)} · ${r.legacy?'이전 작성 계획':'추천 기록'} · ${esc(r.savedAt)}</p></div><div class="actions">${r.legacy?'':`<button data-s-load="${esc(r.id)}">추천 다시 작성</button>`}<button data-s-report="${esc(r.id)}">저장 안내문</button></div></article>`).join(''):'<p class="empty">저장된 수술 추천이 없습니다.</p>';}
$('s-save').addEventListener('click',()=>{try{render();if(!last.ok)return;const p=read();if(!p.name.trim()){const name=prompt('저장할 환자명 / 차트 번호');if(!name?.trim())return;p.name=name.trim();$('s-name').value=p.name;}const r=validateRecord({id:crypto.randomUUID(),savedAt:new Date().toISOString(),patient:p,foodSnapshot:last.food,result:last,referenceDate:S.checkedAt});persist([...records,r]);renderRecords();notify('수술 추천을 저장했습니다.');}catch(e){notify(e.message);}});
$('s-records').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const r=records.find(x=>x.id===(b.dataset.sLoad||b.dataset.sReport));if(!r)return;if(b.dataset.sReport)showReport(report(r.patient,r.result,r.savedAt,r.legacy));else{fields.forEach(k=>$('s-'+k).value=r.patient[k]);$('s-induction').value='';$('s-recoveredAt').value='';$('s-emergency').checked=r.patient.emergency;selectedFood=r.foodSnapshot?.id||'';render();notify('현재 제품 자료로 다시 추천합니다. 예정·회복 시각은 새로 입력하세요.');}});
$('s-load-patient').addEventListener('click',()=>{const p=window.VetDietContext.patient();$('s-form').reset();$('s-name').value=p.name;$('s-species').value=p.species;$('s-weight').value=p.weight;$('s-ageWeeks').value=p.age?(Number(p.age)*365.25/12/7).toFixed(1):'';const c=p.conditions;$('s-profile').value=c.length>1?'other':c.includes('renal')?'renal':c.includes('lowfat')?'lowfat':c.includes('allergy')?'allergy':c.length||['hospital','reproduction'].includes(p.life)||Number(p.bcs)<4||p.mcs!=='normal'?'other':'healthy';selectedFood='';render();notify('현재 환자 정보를 가져왔습니다. 수술 종류·주령·상태를 확인하세요.');});
$('s-backup').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({type:'vetdiet-surgery',version:2,records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='VetDiet-surgery-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('s-restore').addEventListener('click',()=>$('s-restore-file').click());$('s-restore-file').addEventListener('change',async()=>{try{const file=$('s-restore-file').files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('백업은 5 MB 이하여야 합니다.');const incoming=validateBackup(JSON.parse(await file.text())),map=new Map(records.map(r=>[r.id,r]));incoming.forEach(r=>{if(!map.has(r.id))map.set(r.id,r);});persist([...map.values()]);renderRecords();notify('수술 백업을 합쳤습니다. 기존 기록은 유지했습니다.');}catch(e){notify('복원 실패: '+e.message);}finally{$('s-restore-file').value='';}});
  function renderDisease(){const sp=$('d-species').value,id=$('d-topic').value;$('d-content').innerHTML=C.topics.filter(t=>id==='all'||id===t.id).map(t=>{const products=t.purpose?dietProducts().filter(x=>(x.species===sp||x.species==='both')&&x.purposes.includes(t.purpose)):[];return`<article class="panel disease-card"><h2>${esc(t.title)}</h2><dl><dt>식이 목표</dt><dd>${esc(t.goal)}</dd><dt>급여 방법</dt><dd>${esc(t.feeding)}</dd><dt>${sp==='dog'?'강아지':'고양이'}에서 확인</dt><dd>${esc(t[sp])}</dd><dt>재평가</dt><dd>${esc(t.monitor)}</dd><dt>예외 / 주의</dt><dd>${esc(t.caution)}</dd></dl><details><summary>로얄캐닌·힐스 등록 제품 용도 예시 (${products.length}개)</summary>${products.length?'<ul>'+products.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${x.brand==='rc'?'로얄캐닌':'힐스'} · ${esc(x.name)}</a></li>`).join('')+'</ul>':'<p>검증된 제품 매칭 자료가 없습니다. 제품 영양 분석 및 환자 상태를 검토해 선택하세요.</p>'}<p class="muted">개별 적합성·적용 연령·금기는 급여 계획과 제품 출처에서 확인하세요. 여기에서는 제품이나 급여량을 확정하지 않습니다.</p></details><p class="clinical-sources">${sources(t.sources)}</p><p class="footnote">자료 확인: ${C.checkedAt}</p></article>`;}).join('');}
  C.topics.forEach(t=>{const o=document.createElement('option');o.value=t.id;o.textContent=t.title;$('d-topic').append(o);});['d-species','d-topic'].forEach(id=>$(id).addEventListener('change',renderDisease));
  $('d-load-patient').addEventListener('click',()=>{$('d-species').value=document.querySelector('[name=species]:checked').value;const conditions=[...document.querySelectorAll('[name=condition]:checked')].map(x=>x.value),topics=conditions.map(k=>k==='lowfat'?'pancreatitis':k).filter(k=>C.topics.some(t=>t.id===k));if($('goal').value==='loss')topics.push('weight');$('d-topic').value=topics.length===1?topics[0]:'all';$('d-patient-note').textContent='현재 환자: '+($('name').value||'미입력')+' · '+(topics.length?topics.map(k=>k==='pancreatitis'?'저지방 필요 · 췌장염 참고(진단 아님)':C.topics.find(t=>t.id===k).title).join(' / '):'질환 유형을 직접 선택하세요.')+(topics.length>1?' · 복합 조건의 우선순위와 충돌을 함께 검토하세요.':'');renderDisease();});
  render();renderRecords();renderDisease();
  const view=location.hash.slice(1);if(['surgery','disease'].includes(view))document.querySelector(`nav button[data-tab="${view}"]`).click();
})();
